#!/bin/bash
FILE="src/components/ResultsPanel.tsx"

# Use sed to replace the exercise display section
# We need to replace from line 65 to line 69
sed -i '65,69c\                      <div key={index} style={{ marginBottom: \x2712px\x27 }}>\n                        <div style={{ display: \x27flex\x27, justifyContent: \x27space-between\x27, alignItems: \x27flex-start\x27 }}>\n                          <div>\n                            <strong>{exercise.name}</strong>: {exercise.sets}x{exercise.reps}\n                          </div>\n                          {exercise.tiktokLink && (\n                            <div style={{ marginLeft: \x2710px\x27, flexShrink: 0 }}>\n                              <a \n                                href={exercise.tiktokLink} \n                                target=\"_blank\" \n                                rel=\"noopener noreferrer\"\n                                style={{\n                                  fontSize: \x2712px\x27,\n                                  color: \x27#007bff\x27,\n                                  textDecoration: \x27none\x27,\n                                  display: \x27flex\x27,\n                                  alignItems: \x27center\x27,\n                                  gap: \x274px\x27\n                                }}\n                              >\n                                <span style={{ \n                                  backgroundColor: \x27#000\x27, \n                                  color: \x27#fff\x27, \n                                  padding: \x272px 6px\x27, \n                                  borderRadius: \x273px\x27,\n                                  fontSize: \x2710px\x27,\n                                  fontWeight: \x27bold\x27\n                                }}>\n                                  TT\n                                </span>\n                                Watch Form\n                              </a>\n                            </div>\n                          )}\n                        </div>\n                        {exercise.tiktokLink && (\n                          <div style={{ \n                            fontSize: \x2711px\x27, \n                            color: \x27#666\x27, \n                            marginTop: \x272px\x27,\n                            overflow: \x27hidden\x27,\n                            textOverflow: \x27ellipsis\x27,\n                            whiteSpace: \x27nowrap\x27\n                          }}>\n                            TikTok: {exercise.tiktokLink.replace(\x27https://www.\x27, \x27\x27).substring(0, 40)}...\n                          </div>\n                        )}\n                      </div>' "$FILE"

echo "Exercise display updated!"
